		/**
		* 渲染整帧：背景草地 → 围栏 → 狼 → 羊 → 犬 → HUD → overlay。
		* @param ctx - 画布上下文（逻辑坐标系已由 fitCanvas 设好）。
		* @param st - 游戏状态。
		* @param paused - 是否暂停（暂停时叠加 overlay）。
		*/
		function renderSheepdog(ctx, st, paused) {
			const level = LEVELS$7[st.levelIndex];
			const f = fieldRect(level);
			drawBackground(ctx, 480, 600);
			ctx.fillStyle = GRASS_BASE;
			ctx.fillRect(f.x, f.y, f.w, f.h);
			ctx.fillStyle = GRASS_STRIPE;
			for (let sx = f.x; sx < f.x + f.w; sx += 34) ctx.fillRect(sx, f.y, 17, f.h);
			for (const d of st.deco) {
				ctx.strokeStyle = d.shade > .5 ? "rgba(126,168,102,0.5)" : "rgba(70,101,64,0.7)";
				ctx.lineWidth = 1.2;
				ctx.beginPath();
				ctx.moveTo(d.x - d.r / 2, d.y + d.r / 2);
				ctx.lineTo(d.x, d.y - d.r / 2);
				ctx.lineTo(d.x + d.r / 2, d.y + d.r / 2);
				ctx.stroke();
			}
			ctx.strokeStyle = HEDGE;
			ctx.lineWidth = 5;
			ctx.strokeRect(f.x - 2.5, f.y - 2.5, f.w + 5, f.h + 5);
			drawPen(ctx, penRect(level));
			for (const wolf of st.wolves) {
				drawCritter(ctx, wolf.x, wolf.y, Math.atan2(wolf.vy, wolf.vx), st.elapsedMs / 90, "#7d8087", "#5c5f66", "#4a4d54", 1);
				ctx.fillStyle = THEME.bad;
				ctx.beginPath();
				ctx.arc(wolf.x + Math.cos(Math.atan2(wolf.vy, wolf.vx)) * 10, wolf.y + Math.sin(Math.atan2(wolf.vy, wolf.vx)) * 10, 1.3, 0, Math.PI * 2);
				ctx.fill();
			}
			for (const s of st.sheep) drawSheep(ctx, s);
			glow(ctx, accent(0), 8);
			drawCritter(ctx, st.dog.x, st.dog.y, st.dog.heading, st.dog.legPhase, "#f4f4f8", "#2a2a34", "#2a2a34", 1.1);
			noGlow(ctx);
			const accentColor = st.timeLeftMs < 1e4 ? THEME.bad : THEME.text;
			hudPair(ctx, 10, 20, "关卡", String(st.levelIndex + 1) + "/" + String(LEVELS$7.length));
			hudPair(ctx, 240, 20, "入栏", st.pennedCount + "/" + st.sheep.length, "center", accent(2));
			hudPair(ctx, 470, 20, "限时", (st.timeLeftMs / 1e3).toFixed(1) + "s", "right", accentColor);
			hudPair(ctx, 240, 44, "得分", String(st.score), "center", THEME.gold);
			if (st.phase === "won") drawOverlay(ctx, 480, 600, "过关！", "剩余 " + Math.ceil(st.timeLeftMs / 1e3) + " 秒 · 加分已入账 · 即将进入下一关", THEME.good);
			else if (st.phase === "lost") drawOverlay(ctx, 480, 600, "时间到", "还剩 " + (st.sheep.length - st.pennedCount) + " 只羊 · 按 R 重开", THEME.bad);
			else if (st.phase === "campaign-won") drawOverlay(ctx, 480, 600, "全圈完成！", "五关羊群全部入栏 · 总分 " + st.score + " · 按 R 再来一局", THEME.gold);
			else if (paused) drawOverlay(ctx, 480, 600, "暂停", "按 P 继续 · 按 R 重开");
		}
