		function createSheepdogGame(host, options) {
			const canvas = document.createElement("canvas");
			canvas.className = "dmg-game-canvas";
			host.replaceChildren(canvas);
			const fit = fitCanvas(host, canvas, 480, 600);
			if (fit === null) throw new Error("dsh-minigames: sheepdog needs a 2d canvas context");
			const ctx = fit.ctx;
			let state = createSheepdog();
			let running = false;
			let lastScore = -1;
			const input = {
				up: false,
				down: false,
				left: false,
				right: false
			};
			const reportScore = () => {
				if (state.score === lastScore) return;
				lastScore = state.score;
				options?.onScore?.(state.score);
			};
			const onKeyDown = (event) => {
				if (!gameHasFocus(host)) return;
				if (event.ctrlKey || event.altKey || event.metaKey) return;
				switch (event.code) {
					case "ArrowLeft":
					case "KeyA":
						event.preventDefault();
						input.left = true;
						break;
					case "ArrowRight":
					case "KeyD":
						event.preventDefault();
						input.right = true;
						break;
					case "ArrowUp":
					case "KeyW":
						event.preventDefault();
						input.up = true;
						break;
					case "ArrowDown":
					case "KeyS":
						event.preventDefault();
						input.down = true;
						break;
					case "KeyR":
						event.preventDefault();
						reset();
						break;
					case "KeyP":
						event.preventDefault();
						togglePause();
				}
			};
			const onKeyUp = (event) => {
				switch (event.code) {
					case "ArrowLeft":
					case "KeyA":
						input.left = false;
						break;
					case "ArrowRight":
					case "KeyD":
						input.right = false;
						break;
					case "ArrowUp":
					case "KeyW":
						input.up = false;
						break;
					case "ArrowDown":
					case "KeyS": input.down = false;
				}
			};
			const frame = (f) => {
				if (!running) return;
				stepSheepdog(state, f.dt * 1e3, input);
				reportScore();
				if (f.render) renderSheepdog(ctx, state, false);
			};
			const loop = createFrameLoop(frame);
			const reset = () => {
				state = createSheepdog();
				lastScore = -1;
				input.up = input.down = input.left = input.right = false;
				loop.markDirty();
			};
			const togglePause = () => {
				if (running) pause();
				else resume();
			};
			const pause = () => {
				if (!running) return;
				running = false;
				loop.pause();
				renderSheepdog(ctx, state, true);
			};
			const resume = () => {
				if (running) return;
				running = true;
				loop.start();
			};
			window.addEventListener("keydown", onKeyDown);
			window.addEventListener("keyup", onKeyUp);
			focusGameHost(host);
			running = true;
			loop.start();
			renderSheepdog(ctx, state, false);
			return {
				start: resume,
				pause,
				resume,
				destroy: () => {
					running = false;
					loop.destroy();
					fit.dispose();
					window.removeEventListener("keydown", onKeyDown);
					window.removeEventListener("keyup", onKeyUp);
				}
			};
		}
