		//#region src/client/games/hole/index.ts
		/** 每局种子：挂载时取一次，重开换新局号但同一天内可复现。 */
		function dailySeed() {
			const d = /* @__PURE__ */ new Date();
			return d.getFullYear() * 1e4 + (d.getMonth() + 1) * 100 + d.getDate();
		}
		/** 单帧最多补的固定步数（防卡顿后追帧过猛）。 */
		const MAX_STEPS_PER_FRAME = 3;
		/** 浮字存活时长（秒，与渲染层 age 淡出公式匹配）。 */
		const FLOAT_LIFETIME = 1.6;
		function createHoleGame(host, options) {
			const canvas = document.createElement("canvas");
			canvas.className = "dmg-game-canvas";
			canvas.style.touchAction = "none";
			host.replaceChildren(canvas);
			const fit = fitCanvas(host, canvas, 960, 600);
			if (fit === null) throw new Error("dsh-minigames: hole needs a 2d canvas context");
			const ctx = fit.ctx;
			const seed = dailySeed();
			let round = 0;
			let state = createHole(seed, round);
			let running = false;
			let lastScore = -1;
			let acc = 0;
			let clock = 0;
			const cam = {
				x: state.holes[0].x,
				y: state.holes[0].y
			};
			const pointer = {
				x: 480,
				y: 300,
				active: false
			};
			const particles = createParticles();
			let floats = [];
			const pointerFromEvent = (event) => {
				const rect = canvas.getBoundingClientRect();
				pointer.x = (event.clientX - rect.left) * 960 / rect.width;
				pointer.y = (event.clientY - rect.top) * 600 / rect.height;
				pointer.active = true;
			};
			/** 逻辑事件 -> 浮字（世界坐标）与粒子（屏幕坐标）。 */
			const consumeEvents = () => {
				for (const e of state.events) if (e.type === "milestone") {
					floats.push({
						x: e.x,
						y: e.y,
						text: e.text,
						age: 0
					});
					particles.burst(e.x - cam.x + 480, e.y - cam.y + 300, THEME.gold, 18, 200);
				} else if (e.type === "bite") particles.burst(e.x - cam.x + 480, e.y - cam.y + 300, THEME.bad, 14, 180);
			};
			const reportScore = () => {
				const score = state.holes[0].eaten;
				if (score === lastScore) return;
				lastScore = score;
				options?.onScore?.(score);
			};
			const reset = () => {
				round += 1;
				state = createHole(seed, round);
				const p = state.holes[0];
				cam.x = p.x;
				cam.y = p.y;
				acc = 0;
				lastScore = -1;
				floats = [];
				reportScore();
				loop.markDirty();
			};
			const onKeyDown = (event) => {
				if (!gameHasFocus(host)) return;
				if (event.ctrlKey || event.altKey || event.metaKey) return;
				if (event.code === "KeyR") {
					event.preventDefault();
					reset();
				} else if (event.code === "KeyP") {
					event.preventDefault();
					togglePause();
				}
			};
			const onMouseMove = (event) => pointerFromEvent(event);
			const onMouseDown = (event) => pointerFromEvent(event);
			const onMouseLeave = () => {
				pointer.active = false;
			};
			const frame = (f) => {
				if (!running) return;
				clock += f.dt;
				acc += f.dt;
				let steps = 0;
				while (acc >= .03333333333333333 && steps < MAX_STEPS_PER_FRAME) {
					const p = state.holes[0];
					const tx = pointer.active ? cam.x + pointer.x - 480 : p.x;
					const ty = pointer.active ? cam.y + pointer.y - 300 : p.y;
					stepHole(state, {
						targetX: tx,
						targetY: ty
					});
					consumeEvents();
					acc -= TICK;
					steps += 1;
				}
				if (steps === MAX_STEPS_PER_FRAME) acc = 0;
				const p = state.holes[0];
				const k = Math.min(1, f.dt * 6);
				cam.x += (p.x - cam.x) * k;
				cam.y += (p.y - cam.y) * k;
				for (const fl of floats) fl.age += f.dt / FLOAT_LIFETIME;
				floats = floats.filter((fl) => fl.age < 1);
				reportScore();
				if (f.render || particles.size() > 0) {
					renderHole(ctx, state, {
						camX: cam.x,
						camY: cam.y,
						time: clock,
						paused: false,
						floats
					});
					particles.tick(ctx, f.dt * 1e3);
				}
			};
			const loop = createFrameLoop(frame);
			const pauseFrame = () => {
				renderHole(ctx, state, {
					camX: cam.x,
					camY: cam.y,
					time: clock,
					paused: true,
					floats
				});
			};
			const togglePause = () => {
				if (running) pause();
				else resume();
			};
			const pause = () => {
				if (!running) return;
				running = false;
				loop.pause();
				pauseFrame();
			};
			const resume = () => {
				if (running) return;
				running = true;
				acc = 0;
				loop.start();
				loop.markDirty();
			};
			canvas.addEventListener("mousemove", onMouseMove);
			canvas.addEventListener("mousedown", onMouseDown);
			canvas.addEventListener("mouseleave", onMouseLeave);
			window.addEventListener("keydown", onKeyDown);
			focusGameHost(host);
			running = true;
			loop.start();
			reportScore();
			return {
				start: resume,
				pause,
				resume,
				destroy: () => {
					running = false;
					loop.destroy();
					fit.dispose();
					canvas.removeEventListener("mousemove", onMouseMove);
					canvas.removeEventListener("mousedown", onMouseDown);
					canvas.removeEventListener("mouseleave", onMouseLeave);
					window.removeEventListener("keydown", onKeyDown);
				}
			};
		}
